// Grok 응답 파싱 및 정리

const response = $input.item.json;
const content = response.choices[0].message.content;

// JSON 추출 (코드 블록 제거)
let jsonContent = content;
if (content.includes('```json')) {
  jsonContent = content.split('```json')[1].split('```')[0].trim();
} else if (content.includes('```')) {
  jsonContent = content.split('```')[1].split('```')[0].trim();
}

const event = JSON.parse(jsonContent);

// 메타데이터 추가
event.tweet_id = $node["X Watch - Official Accounts"].json.id_str;
event.tweet_created_at = $node["X Watch - Official Accounts"].json.created_at;
event.tweet_author = $node["X Watch - Official Accounts"].json.user.screen_name;
event.processed_at = new Date().toISOString();

return { json: event };

// AI 리포트 생성 (폴백 체인)
// 1. Grok 4.1 Fast → 2. Qwen 2.5 VL 72B → 3. GPT-4o-mini → 4. Claude 3.5 Haiku

const axios = require('axios');

const OPENROUTER_API_KEY = $env.OPENROUTER_API_KEY;
const BASE_URL = 'https://openrouter.ai/api/v1/chat/completions';

const MODELS = [
  { name: 'Grok 4.1 Fast', id: 'x-ai/grok-4.1-fast', timeout: 10000 },
  { name: 'Qwen 2.5 VL 72B', id: 'qwen/qwen2.5-vl-72b-instruct', timeout: 15000 },
  { name: 'GPT-4o-mini', id: 'openai/gpt-4o-mini', timeout: 15000 },
  { name: 'Claude 3.5 Haiku', id: 'anthropic/claude-3.5-haiku', timeout: 20000 }
];

const event = $node["Event 구조화"].json;
const context = $node["Neo4j - Context 계산"].json;

const prompt = `Generate NBA betting signal report.\n\nEvent:\n${JSON.stringify(event, null, 2)}\n\nContext:\n${JSON.stringify(context, null, 2)}\n\nProvide:\n1. Impact Assessment (0-10)\n2. Historical Pattern\n3. Betting Implications\n4. Confidence Level\n\nKeep response concise and actionable.`;

async function callAI(model) {
  const headers = {
    'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://github.com/nba-realtime-pipeline',
    'X-Title': 'NBA Real-time Event Analyzer'
  };

  const payload = {
    model: model.id,
    messages: [{ role: 'user', content: prompt }],
    temperature: 0.3,
    max_tokens: 1000
  };

  try {
    console.log(`[${model.name}] Attempting...`);
    const response = await axios.post(BASE_URL, payload, { headers, timeout: model.timeout });
    const content = response.data.choices[0].message.content;
    console.log(`[${model.name}] ✅ Success`);
    return { success: true, model: model.name, content };
  } catch (error) {
    console.error(`[${model.name}] ❌ Failed: ${error.message}`);
    return { success: false, model: model.name, error: error.message };
  }
}

async function runWithFallback() {
  const attempts = [];
  for (const model of MODELS) {
    const result = await callAI(model);
    attempts.push(result);
    if (result.success) {
      return {
        json: {
          report: result.content,
          model_used: result.model,
          fallback_attempts: attempts.length,
          all_attempts: attempts
        }
      };
    }
    console.log(`[Fallback] Trying next model...`);
  }
  return {
    json: {
      error: 'All AI models failed',
      report: `⚠️ AI 리포트 생성 실패\n\n모든 모델이 응답하지 않았습니다.\n수동 확인 필요.`,
      all_attempts: attempts
    }
  };
}

return await runWithFallback();

